package com.example.practice;

import org.jpos.iso.ISOCurrency;
import org.jpos.iso.ISOException;
import org.jpos.iso.ISOMsg;

import java.math.BigDecimal;

/**
 * The merchant portal's refunds. A merchant types the amount to refund as they would write it
 * ("42.10", "25000"), and the portal shows the amounts of past purchases from their field 4.
 */
public class RefundAmounts {

    /** A refund (0200, processing code 20) for part or all of an earlier purchase, in its currency. */
    public ISOMsg refund(ISOMsg purchase, String typed) throws ISOException {
        String currency = purchase.getString(49);
        ISOMsg refund = new ISOMsg("0200");
        refund.set(2, purchase.getString(2));
        refund.set(3, "200000");
        refund.set(4, field4(typed, currency));
        refund.set(41, purchase.getString(41));
        refund.set(49, currency);
        return refund;
    }

    /** What the portal shows for a past purchase. */
    public String shown(ISOMsg purchase) {
        return shown(purchase.getString(4), purchase.getString(49));
    }

    /**
     * Field 4 for an amount typed by the merchant in the given currency (ISO 4217 numeric code).
     * Throws IllegalArgumentException when the amount can't be sent in that currency as typed.
     */
    String field4(String typed, String currency) {
        try {
            return ISOCurrency.toISO87String(new BigDecimal(typed), currency);
        } catch (ArithmeticException e) {
            throw new IllegalArgumentException(typed + " is finer than currency " + currency + " allows", e);
        }
    }

    /** The amount in field 4 as the merchant would write it, for example 42.10. */
    String shown(String field4, String currency) {
        return ISOCurrency.parseFromISO87String(field4, currency).toPlainString();
    }
}

import com.example.practice.RefundAmounts;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.jpos.iso.ISOMsg;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        Logger root = Logger.getLogger("");
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            RefundAmounts portal = new RefundAmounts();
            ISOMsg yen = purchase("000000004800", "392");
            ISOMsg dinar = purchase("000000015250", "414");
            ISOMsg euro = purchase("000000008990", "978");
            System.out.println("yen purchase shown: " + portal.shown(yen));
            System.out.println("Kuwaiti dinar purchase shown: " + portal.shown(dinar));
            System.out.println("yen refund of 1500, field 4: " + portal.refund(yen, "1500").getString(4));
            System.out.println("dinar refund of 3.75, field 4: " + portal.refund(dinar, "3.75").getString(4));
            System.out.println("euro refund of 12.5, field 4: " + portal.refund(euro, "12.5").getString(4));
            try {
                portal.refund(yen, "99.9");
            } catch (IllegalArgumentException refused) {
                System.out.println("yen refund of 99.9 refused: " + refused.getMessage());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static ISOMsg purchase(String amount, String currency) throws Exception {
        ISOMsg m = new ISOMsg("0200");
        m.set(2, "4000000000000002");
        m.set(3, "000000");
        m.set(4, amount);
        m.set(41, "TERM1100");
        m.set(49, currency);
        return m;
    }
}

